// Create a new runtime and initialize bookkeeping attributes.
JSRuntime *rt = JS_NewRuntime();
if (!rt) { FUZZ_BAIL(); }
// Track live status and number of live contexts attached to this runtime.
FUZZ_SET_ATTR_INT(rt, "alive", 1);
FUZZ_SET_ATTR_INT(rt, "ctx_refcount", 0);
// Track debug flags we set later (start at 0 by default).
FUZZ_SET_ATTR_INT(rt, "dump_flags", 0);
// Validation: Created runtime is non-null and marked alive; returned for pooling.

// Ensure runtime is alive.
if (FUZZ_GET_ATTR_INT(rt, "alive") != 1) { FUZZ_BAIL(); }
// Per API, the info string lifetime must exceed the runtime lifetime. Use a static string literal to satisfy this.
const char *info = "fuzz-runtime-info";
JS_SetRuntimeInfo(rt, info);
// Optionally record that info was set for downstream checks.
FUZZ_SET_ATTR_INT(rt, "info_set", 1);
// Validation: Uses a static literal to satisfy lifetime; runtime remains owned and is returned.

// Ensure runtime is alive.
if (FUZZ_GET_ATTR_INT(rt, "alive") != 1) { FUZZ_BAIL(); }
// Pick a reasonable limit (keep small for fuzz performance); 0 disables.
size_t limit = (size_t)(*FUZZ_PARAM(unsigned int) % (1024 * 1024 + 1));
JS_SetMemoryLimit(rt, limit);
// Track last-set limit for potential diagnostics.
FUZZ_SET_ATTR_INT(rt, "mem_limit_set", 1);
// Validation: Limit is within small range or zero; runtime retained.

// Ensure runtime is alive.
if (FUZZ_GET_ATTR_INT(rt, "alive") != 1) { FUZZ_BAIL(); }
uint64_t flags = (uint64_t)(*FUZZ_PARAM(unsigned long long));
JS_SetDumpFlags(rt, flags);
// Mirror into attribute for potential cross-checks by other stubs.
// Note: attribute API is int, so we store a truncated view for hints only.
FUZZ_SET_ATTR_INT(rt, "dump_flags", (int)(flags & 0x7fffffff));
// Validation: Flags set with an arbitrary bitmask; runtime persisted.

// Ensure runtime is alive and call getter. The return value is unused in the harness.
if (FUZZ_GET_ATTR_INT(rt, "alive") != 1) { FUZZ_BAIL(); }
uint64_t current = JS_GetDumpFlags(rt);
(void)current;
// Validation: Non-mutating; runtime preserved for pool reuse.

// Check runtime validity and query the threshold.
if (FUZZ_GET_ATTR_INT(rt, "alive") != 1) { FUZZ_BAIL(); }
size_t thr = JS_GetGCThreshold(rt);
(void)thr;
// Validation: Getter-only call; runtime is returned unchanged.

// Ensure runtime is alive and set a small GC threshold.
if (FUZZ_GET_ATTR_INT(rt, "alive") != 1) { FUZZ_BAIL(); }
size_t gc_threshold = (size_t)(*FUZZ_PARAM(unsigned int) % (1024 * 1024 + 1));
JS_SetGCThreshold(rt, gc_threshold);
// Record that we've set a threshold.
FUZZ_SET_ATTR_INT(rt, "gc_thr_set", 1);
// Validation: Threshold constrained; runtime preserved.

// Ensure runtime is alive and set a bounded stack size (or 0 to disable).
if (FUZZ_GET_ATTR_INT(rt, "alive") != 1) { FUZZ_BAIL(); }
size_t stack_size = (size_t)(*FUZZ_PARAM(unsigned int) % (512 * 1024 + 1));
JS_SetMaxStackSize(rt, stack_size);
FUZZ_SET_ATTR_INT(rt, "stack_size_set", 1);
// Validation: Non-destructive; runtime is returned.

// Ensure runtime is alive and notify potential thread change.
if (FUZZ_GET_ATTR_INT(rt, "alive") != 1) { FUZZ_BAIL(); }
JS_UpdateStackTop(rt);
// Validation: Simple notification; runtime preserved.

// Create a runtime using default allocators by passing NULL function table.
const JSMallocFunctions *mf = (const JSMallocFunctions *)0;
void *opaque = (void *)0; // ignored when mf == NULL
JSRuntime *rt = JS_NewRuntime2(mf, opaque);
if (!rt) { FUZZ_BAIL(); }
// Initialize bookkeeping attributes as in JS_NewRuntime.
FUZZ_SET_ATTR_INT(rt, "alive", 1);
FUZZ_SET_ATTR_INT(rt, "ctx_refcount", 0);
FUZZ_SET_ATTR_INT(rt, "dump_flags", 0);
// Validation: Constructed runtime with default allocators; returned to pool.

// Enforce no live contexts are attached to this runtime before freeing.
if (FUZZ_GET_ATTR_INT(rt, "alive") != 1) { FUZZ_BAIL(); }
int ctx_refs = FUZZ_GET_ATTR_INT(rt, "ctx_refcount");
if (ctx_refs != 0) { FUZZ_BAIL(); }
// Safe to free now.
JS_FreeRuntime(rt);
// Mark as dead to prevent reuse (not returned as output).
FUZZ_SET_ATTR_INT(rt, "alive", 0);
// Validation: Prevents destroying a runtime with live contexts via refcount gate.

// Ensure runtime is alive and retrieve the opaque pointer.
if (FUZZ_GET_ATTR_INT(rt, "alive") != 1) { FUZZ_BAIL(); }
void *opq = JS_GetRuntimeOpaque(rt);
(void)opq;
// Validation: Read-only query; runtime preserved.

// Ensure runtime is alive and set an arbitrary opaque pointer.
if (FUZZ_GET_ATTR_INT(rt, "alive") != 1) { FUZZ_BAIL(); }
void *opaque = (void*)(uintptr_t)(*FUZZ_PARAM(uintptr_t));
JS_SetRuntimeOpaque(rt, opaque);
// Mirror for potential downstream checks.
FUZZ_SET_ATTR_PTR(rt, "opaque", opaque);
// Validation: Opaque pointer set to an arbitrary stable value; runtime retained.

// Ensure runtime is alive and force a GC cycle.
if (FUZZ_GET_ATTR_INT(rt, "alive") != 1) { FUZZ_BAIL(); }
JS_RunGC(rt);
// Validation: No ownership changes; runtime returned.

// Ensure runtime is alive.
if (FUZZ_GET_ATTR_INT(rt, "alive") != 1) { FUZZ_BAIL(); }
// Create a temporary context to fabricate a JS object to test liveness.
JSContext *tmp = JS_NewContext(rt);
if (!tmp) { FUZZ_BAIL(); }
JSValue obj = JS_NewObject(tmp);
// The function expects a JS object value; API is read-only.
bool live = JS_IsLiveObject(rt, obj);
(void)live;
// Clean up temporaries.
JS_FreeValue(tmp, obj);
JS_FreeContext(tmp);
// Validation: Uses a temporary context/value and cleans them; runtime preserved.

// Ensure runtime is alive and create a context.
if (FUZZ_GET_ATTR_INT(rt, "alive") != 1) { FUZZ_BAIL(); }
JSContext *ctx = JS_NewContext(rt);
if (!ctx) { FUZZ_BAIL(); }
// Initialize context bookkeeping and link to parent runtime.
FUZZ_SET_ATTR_INT(ctx, "alive", 1);
FUZZ_SET_ATTR_INT(ctx, "refcount", 1); // owned references count; JS_DupContext increments this
FUZZ_SET_ATTR_PTR(ctx, "rt", rt);
// Increment runtime's context refcount.
int ctx_refs = FUZZ_GET_ATTR_INT(rt, "ctx_refcount");
FUZZ_SET_ATTR_INT(rt, "ctx_refcount", ctx_refs + 1);
// Validation: Context is linked to its runtime and tracked for safe teardown; both returned.

// Validate context is alive and retrieve refcount/runtime linkage.
if (FUZZ_GET_ATTR_INT(ctx, "alive") != 1) { FUZZ_BAIL(); }
int refcount = FUZZ_GET_ATTR_INT(ctx, "refcount");
if (refcount <= 0) { FUZZ_BAIL(); }
JSRuntime *rt = (JSRuntime*)FUZZ_GET_ATTR_PTR(ctx, "rt");
if (!rt || FUZZ_GET_ATTR_INT(rt, "alive") != 1) { FUZZ_BAIL(); }
// Free (decrement internal engine refcount) once per call.
JS_FreeContext(ctx);
refcount -= 1;
if (refcount > 0) {
    // Context remains alive; update refcount and keep it in the pool.
    FUZZ_SET_ATTR_INT(ctx, "refcount", refcount);
    // Return ctx as it is still valid.
} else {
    // Fully released: mark dead and drop from outputs; also decrement runtime's ctx_refcount.
    FUZZ_SET_ATTR_INT(ctx, "alive", 0);
    int ctx_refs = FUZZ_GET_ATTR_INT(rt, "ctx_refcount");
    FUZZ_SET_ATTR_INT(rt, "ctx_refcount", ctx_refs - 1);
    // Do not return ctx; signal to harness by bailing from output path.
    // We cannot alter declared outputs at runtime; emulate drop by marking invalid and letting pool discard.
}
// Validation: Balances JS_DupContext via refcount attr; marks/decrements runtime refcount when reaching zero.

// Validate context is alive.
if (FUZZ_GET_ATTR_INT(ctx, "alive") != 1) { FUZZ_BAIL(); }
// Increment engine-side refcount and mirror in our attributes.
JSContext *dup = JS_DupContext(ctx);
if (!dup) { FUZZ_BAIL(); }
int refcount = FUZZ_GET_ATTR_INT(ctx, "refcount");
FUZZ_SET_ATTR_INT(ctx, "refcount", refcount + 1);
(void)dup; // same pointer as ctx in QuickJS; we only keep a single object in the pool.
// Validation: Mirrors engine refcount bump; returns the same ctx for continued use.

// Validate context is alive.
if (FUZZ_GET_ATTR_INT(ctx, "alive") != 1) { FUZZ_BAIL(); }
// Retrieve the user-defined opaque pointer; do not assume ownership.
void *opaque = JS_GetContextOpaque(ctx);
(void)opaque;
// Validation: Read-only getter; ctx remains valid and is returned to the pool.

// Validate context is alive before mutation.
if (FUZZ_GET_ATTR_INT(ctx, "alive") != 1) { FUZZ_BAIL(); }
// Assign an arbitrary opaque pointer value. Lifetime is managed by the fuzzer; QuickJS only stores it.
void *opaque = (void*)(uintptr_t)(*FUZZ_PARAM(uintptr_t));
JS_SetContextOpaque(ctx, opaque);
// Mirror in attributes for downstream checks.
FUZZ_SET_ATTR_PTR(ctx, "opaque", opaque);
// Validation: Sets an opaque pointer without transferring ownership; ctx preserved.

// Validate context is alive and linked to a runtime.
if (FUZZ_GET_ATTR_INT(ctx, "alive") != 1) { FUZZ_BAIL(); }
JSRuntime *rt_attr = (JSRuntime*)FUZZ_GET_ATTR_PTR(ctx, "rt");
if (!rt_attr || FUZZ_GET_ATTR_INT(rt_attr, "alive") != 1) { FUZZ_BAIL(); }
// Call the API and sanity-check pointer equality with our linkage attribute.
JSRuntime *rt_api = JS_GetRuntime(ctx);
FUZZ_ASSERT(rt_api == rt_attr, "JS_GetRuntime must return the owning runtime");
(void)rt_api;
// Validation: Confirms runtime association; returns ctx only as ownership is unchanged.

// Set the prototype object for a registered custom class ID.
// Requirements enforced: ctx valid, class_id registered, obj ownership consumed by API.
if (FUZZ_GET_ATTR_INT(ctx, "alive") != 1) { FUZZ_BAIL(); }
JSRuntime *rt = (JSRuntime*)FUZZ_GET_ATTR_PTR(ctx, "rt");
if (!rt || FUZZ_GET_ATTR_INT(rt, "alive") != 1) { FUZZ_BAIL(); }
// Allocate a new class ID and register a minimal class definition with static lifetime name.
JSClassID class_id = 0;
(void)JS_NewClassID(rt, &class_id);
static const char kFuzzClassName[] = "FuzzClass"; // static storage -> lifetime exceeds runtime
JSClassDef def = {0};
def.class_name = kFuzzClassName;
// All hooks NULL to keep behavior simple and safe.
int rc = JS_NewClass(rt, class_id, &def);
if (rc != 0) { FUZZ_BAIL(); }
// Create a prototype object; ownership transfers to JS_SetClassProto.
JSValue proto_obj = JS_NewObject(ctx);
// Set the prototype for this class id; obj is consumed regardless of success, per API semantics.
JS_SetClassProto(ctx, class_id, proto_obj);
// Track the last registered class id on this context for downstream getters.
FUZZ_SET_ATTR_INT(ctx, "last_class_id", (int)class_id);
FUZZ_SET_ATTR_INT(ctx, "class_registered", 1);
// Validation: Class id allocated and registered, proto created and transferred; ctx remains valid.

