// Abstract equality comparison (==) between two values. Create simple values and compare.
if (FUZZ_GET_ATTR_INT(ctx, "alive") != 1) { FUZZ_BAIL(); }
// Generate two values of possibly different types to exercise code paths.
std::string s = FUZZ_PARAM_STR();
double d1 = (double)(*FUZZ_PARAM(unsigned int) % 1000);
double d2 = (double)(*FUZZ_PARAM(unsigned int) % 1000);
